typedef struct{
	void *pI2C; //I2C_HandleTypeDef
	double VREF;
	double AmpGain;
	uint8_t CurrentChannel;

	struct{
		uint8_t Channel;
		NAU7802_Gain_t Gain;
		NAU7802_VLDO_t VLDO;
		NAU7802_SamplingRate_t SamplingRate;
	}Registers;

	struct{
		double SumOfAnalog;
		uint8_t ReadCount;
	}OverSampling;

	uint8_t ErrorCount;
	uint8_t ProcessStep;
	int32_t ReadData;
	uint32_t Timer;

	uint8_t IsOpen;
	uint8_t IsOpening;
	uint8_t IsADConversion;
}NAU7802_t;

extern oResult_t NAU7802_Init(NAU7802_t *pDev, I2C_HandleTypeDef *pI2C, NAU7802_VLDO_t VLDO);
